for c in ['topview','corner3','corner4']:
 o=r.observe(c); a=o['rgb']; d=o['depth_m'];
 red=(a[:,:,0]>130)&(a[:,:,0]>a[:,:,1]*1.5)&(a[:,:,0]>a[:,:,2]*1.4)
 blue=(a[:,:,2]>100)&(a[:,:,2]>a[:,:,0]*1.3)&(a[:,:,2]>a[:,:,1]*1.2)
 print('\n',c)
 for mask in [red,blue]:
  yy,xx=np.where(mask); print('n',len(xx), 'bbox', (xx.min(),yy.min(),xx.max(),yy.max()) if len(xx) else None, 'depth med',np.median(d[yy,xx]) if len(xx) else None)
  if len(xx): print('sample',list(zip(xx[::max(1,len(xx)//10)][:12],yy[::max(1,len(yy)//10)][:12])))
